#!/usr/bin/env node
// Generates the SwiftUI design tokens from design/tokens.json. Pure and offline: same input, same output.
//
//   node scripts/generate-tokens.mjs            write AppCore/Sources/AppCore/Common/UI/DesignTokens.generated.swift
//   node scripts/generate-tokens.mjs --check    exit 1 if the generated file is not up to date (for CI)
//
// design/tokens.json comes from scripts/figma/extract-tokens.js, see scripts/README-tokens.md.
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const input = join(root, 'design/tokens.json')
const output = join(root, 'AppCore/Sources/AppCore/Common/UI/DesignTokens.generated.swift')

const tokens = JSON.parse(readFileSync(input, 'utf8'))

// "Brand/Primary Light" -> "brandPrimaryLight", "SF Pro/Title2/Regular" (prefix removed) -> "title2Regular"
const identifier = (path) => {
  const words = path.split(/[^A-Za-z0-9]+/).filter(Boolean)
  const id = words.map((w, i) => (i === 0 ? w[0].toLowerCase() + w.slice(1) : w[0].toUpperCase() + w.slice(1))).join('')
  return /^[0-9]/.test(id) ? `_${id}` : id
}

const unique = (kind, names) => {
  const seen = new Map()
  for (const n of names) {
    const id = identifier(n)
    if (seen.has(id)) throw new Error(`${kind}: "${n}" and "${seen.get(id)}" both become \`${id}\``)
    seen.set(id, n)
  }
}

// ---- Colours ---------------------------------------------------------------------------------------------

const modes = tokens.modes
const resolveColor = (name, mode, depth = 0) => {
  if (depth > 10) throw new Error(`alias cycle at ${name}`)
  const token = tokens.colors[name]
  if (!token) throw new Error(`unknown colour alias target: ${name}`)
  const v = token.values[mode]
  if (v === undefined) throw new Error(`colour ${name} has no value for mode ${mode}`)
  return typeof v === 'string' ? v : resolveColor(v.alias, mode, depth + 1)
}

const swiftColor = (hex) => {
  const n = (i) => (parseInt(hex.slice(i, i + 2), 16) / 255).toFixed(4).replace(/\.?0+$/, '')
  const a = hex.length === 9 ? parseInt(hex.slice(7, 9), 16) / 255 : 1
  const opacity = a === 1 ? '' : `, opacity: ${a.toFixed(4).replace(/\.?0+$/, '')}`
  return `Color(red: ${n(1) || 0}, green: ${n(3) || 0}, blue: ${n(5) || 0}${opacity})`
}

const light = modes.find((m) => m.toLowerCase() === 'light') ?? modes[0]
const dark = modes.find((m) => m.toLowerCase() === 'dark')

unique('colors', Object.keys(tokens.colors))
const colorLines = Object.keys(tokens.colors).map((name) => {
  const l = swiftColor(resolveColor(name, light))
  const value = dark ? `Color(light: ${l}, dark: ${swiftColor(resolveColor(name, dark))})` : l
  return `    /// ${name}\n    static let ${identifier(name)} = ${value}`
})

// ---- Typography ------------------------------------------------------------------------------------------
// The Figma text styles are Apple's. Where a style is one of the system text styles we use it (so it scales
// with Dynamic Type) and check that Figma agrees with iOS on the size; otherwise we fall back to fixed sizes.

const textStyles = {
  LargeTitle: ['.largeTitle', 34],
  Title1: ['.title', 28],
  Title2: ['.title2', 22],
  Title3: ['.title3', 20],
  Headline: ['.headline', 17],
  Body: ['.body', 17],
  Callout: ['.callout', 16],
  Subheadline: ['.subheadline', 15],
  Footnote: ['.footnote', 13],
  Caption1: ['.caption', 12],
  Caption2: ['.caption2', 11],
}

const weight = (w) =>
  w == null ? '.regular'
    : w < 350 ? '.light' : w < 450 ? '.regular' : w < 550 ? '.medium' : w < 650 ? '.semibold' : w < 750 ? '.bold' : '.heavy'

const fontNames = Object.keys(tokens.typography)
const fontId = (path) => identifier(path.replace(/^SF Pro\//, ''))
unique('typography', fontNames.map((n) => n.replace(/^SF Pro\//, '')))

const fontLines = fontNames.map((name) => {
  const t = tokens.typography[name]
  const group = name.split('/')[1]
  const known = textStyles[group]
  let value
  if (known) {
    if (known[1] !== t.size) {
      throw new Error(`${name}: Figma size ${t.size} differs from iOS ${group} (${known[1]}). Decide whether that is intended.`)
    }
    value = `Font.system(${known[0]}, design: .default, weight: ${weight(t.weight)})`
  } else {
    value = `Font.system(size: ${t.size}, weight: ${weight(t.weight)})`
  }
  return `    /// ${name}\n    static let ${fontId(name)} = ${value}`
})

// ---- Output ----------------------------------------------------------------------------------------------

const out = `// GENERATED by scripts/generate-tokens.mjs from design/tokens.json. Do not edit.
// Change the design in Figma, run scripts/figma/extract-tokens.js (see scripts/README-tokens.md), then
// \`node scripts/generate-tokens.mjs\`.

import SwiftUI
${dark ? `import UIKit

extension Color {
    /// A colour that follows the interface style.
    init(light: Color, dark: Color) {
        self.init(uiColor: UIColor { $0.userInterfaceStyle == .dark ? UIColor(dark) : UIColor(light) })
    }
}
` : ''}
/// The design system's colours (Figma variable collection "Colors").
enum AppColor {
${colorLines.join('\n')}
}

/// The design system's text styles (Figma text styles "SF Pro/…").
enum AppFont {
${fontLines.join('\n')}
}
`

if (process.argv.includes('--check')) {
  if (!existsSync(output) || readFileSync(output, 'utf8') !== out) {
    console.error('DesignTokens.generated.swift is out of date. Run: node scripts/generate-tokens.mjs')
    process.exit(1)
  }
  console.log('Design tokens are up to date.')
} else {
  writeFileSync(output, out)
  console.log(`Wrote ${output.replace(root + '/', '')}`)
}
